const preencherCamposLocaisReproducaoSeAusentes = `-- name: PreencherCamposLocaisReproducaoSeAusentes :exec
UPDATE entity SET
    watched = COALESCE(watched, ?),
    play_count = COALESCE(play_count, ?),
    user_rating = COALESCE(user_rating, ?),
    last_played_at = COALESCE(last_played_at, ?),
    resume_position_seconds = COALESCE(resume_position_seconds, ?),
    resume_total_seconds = COALESCE(resume_total_seconds, ?)
WHERE id = ?
`

type PreencherCamposLocaisReproducaoSeAusentesParams struct {
	Watched               sql.NullInt64
	PlayCount             sql.NullInt64
	UserRating            sql.NullFloat64
	LastPlayedAt          sql.NullString
	ResumePositionSeconds sql.NullFloat64
	ResumeTotalSeconds    sql.NullFloat64
	ID                    string
}

// Preenche os campos LOCAIS de reproducao (briefing 0088) SO onde ainda
// estao NULL (COALESCE) -- nunca sobrescreve um valor ja presente (mesmo
// espirito de "override do dono vence"/"nao-destrutivo", AGENTS.md). Chamada
// pelo endpoint POST /entities/{id}/refresh-files apos ler o .nfo em disco
// (internal/localmedia.ExtrairCamposUsuario); parametros ausentes no .nfo
// entram como NULL/zero-value, o COALESCE cuida do resto.
func (q *Queries) PreencherCamposLocaisReproducaoSeAusentes(ctx context.Context, arg PreencherCamposLocaisReproducaoSeAusentesParams) error {
	_, err := q.db.ExecContext(ctx, preencherCamposLocaisReproducaoSeAusentes,
		arg.Watched,
		arg.PlayCount,
		arg.UserRating,
		arg.LastPlayedAt,
		arg.ResumePositionSeconds,
		arg.ResumeTotalSeconds,
		arg.ID,
	)
	return err
}

const upsertEntityCatalogCompleteness = `-- name: UpsertEntityCatalogCompleteness :exec
INSERT INTO entity_catalog_completeness (
    entity_id, complete, missing_json
) VALUES (
    ?1, ?2, ?3
)
ON CONFLICT (entity_id) DO UPDATE SET
    complete = excluded.complete,
    missing_json = excluded.missing_json,
    evaluated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
`

type UpsertEntityCatalogCompletenessParams struct {
	EntityID    string
	Complete    int64
	MissingJson string
}

// Grava (ou substitui) o resultado da avaliacao de completude de CATALOGACAO
// (briefing 0058) de UM item -- chamada pelo recalculo em lote
// (RecalcularCompletudeCatalogacao, job saude_biblioteca). Conflito na PK
// (entity_id) atualiza complete/missing_json e recarimba evaluated_at --
// nunca cria uma segunda linha para a mesma entity (1:1, mesmo padrao de
// UpsertAppSetting).
func (q *Queries) UpsertEntityCatalogCompleteness(ctx context.Context, arg UpsertEntityCatalogCompletenessParams) error {
	_, err := q.db.ExecContext(ctx, upsertEntityCatalogCompleteness, arg.EntityID, arg.Complete, arg.MissingJson)
	return err
}
